"""Jotdown's task store: one JSON file."""
import json
import os
from pathlib import Path

PATH = Path.home() / ".jotdown.json"


def load():
    if not PATH.exists():
        return []
    return json.loads(PATH.read_text())


def save(tasks):
    tmp = PATH.with_suffix(".tmp")
    tmp.write_text(json.dumps(tasks, indent=2))
    os.replace(tmp, PATH)

