"""Reading and saving the one JSON file that holds the list."""
import json
import os
from pathlib import Path

class BrokenFile(Exception):
    pass


def load(path):
    path = Path(path)
    if not path.exists():
        return {"version": 1, "next_id": 1, "tasks": []}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except ValueError as error:
        raise BrokenFile(f"{path}: not a Jotdown list ({error})")
    if not isinstance(data, dict) or not isinstance(data.get("tasks"), list):
        raise BrokenFile(f"{path}: not a Jotdown list")
    return data


def save(data, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    new = path.with_name(path.name + ".new")
    with open(new, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)
        f.flush()
        os.fsync(f.fileno())
    os.replace(new, path)

