"""Reading and saving the one JSON file that holds the list."""
import json
import os
from pathlib import Path

# The list lives in data/tasks.json in the project folder, the folder that holds jotdown/,
# so every command and the page find the same list whichever folder they run from.
DATA_PATH = Path(__file__).resolve().parent.parent / "data" / "tasks.json"

FORMAT_VERSION = 1


class StoreError(Exception):
    """The data file exists but cannot be read as a list. The message says why."""


def new_list():
    """The empty list that a missing data file stands for."""
    return {"version": FORMAT_VERSION, "next_id": 1, "tasks": []}


class Store:
    """Loads and saves the list in one JSON file."""

    def __init__(self, path=None):
        self.path = Path(path) if path else DATA_PATH

    def load(self):
        """Return the list. A missing file is a new, empty list. A file that cannot be read raises StoreError."""
        try:
            text = self.path.read_text(encoding="utf-8")
        except FileNotFoundError:
            return new_list()
        except OSError as error:
            raise StoreError(f"Cannot read {self.path}: {error.strerror}. It was left as it is.") from None
        try:
            data = json.loads(text)
        except ValueError as error:
            raise StoreError(f"{self.path} is not valid JSON ({error}). It was left as it is.") from None
        if not _is_a_list(data):
            raise StoreError(f"{self.path} does not hold a Jotdown list. It was left as it is.")
        return data

    def save(self, data):
        """Write the whole list to a new file beside the old one, then rename it over the old one.

        A save that is cut off leaves the old file whole.
        """
        self.path.parent.mkdir(parents=True, exist_ok=True)
        temp = self.path.with_name(self.path.name + ".new")
        try:
            with open(temp, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2, ensure_ascii=False)
                f.write("\n")
                f.flush()
                os.fsync(f.fileno())
            os.replace(temp, self.path)
        except BaseException:
            temp.unlink(missing_ok=True)
            raise


def _is_a_list(data):
    return (
        isinstance(data, dict)
        and data.get("version") == FORMAT_VERSION
        and isinstance(data.get("next_id"), int)
        and isinstance(data.get("tasks"), list)
    )

