"""What a task is, and what adding, finishing and editing one do. The commands and the page share these rules."""
import datetime

REPEAT_DAYS = {"daily": 1, "weekly": 7}


class TaskError(Exception):
    """The request cannot be done. The message says why."""


def clean_tags(tags):
    """Tags are lowercase, without the #, sorted, and each one once."""
    cleaned = {tag.strip().lstrip("#").strip().lower() for tag in tags}
    return sorted(tag for tag in cleaned if tag)


def clean_title(title):
    title = " ".join(title.split())
    if not title:
        raise TaskError("A task needs a title.")
    return title


def add_task(data, title, *, today, due=None, tags=(), repeat=None):
    """Add a task to the list and return it. A repeating task with no due date is due today."""
    title = clean_title(title)
    if repeat is not None and repeat not in REPEAT_DAYS:
        raise TaskError(f"A task repeats daily or weekly, not {repeat!r}.")
    if repeat and due is None:
        due = today
    task = {
        "id": data["next_id"],
        "title": title,
        "done": False,
        "due": due.isoformat() if due else None,
        "tags": clean_tags(tags),
        "repeat": repeat,
        "scheduled": due.isoformat() if repeat else None,
    }
    data["next_id"] += 1
    data["tasks"].append(task)
    return task


def find_task(data, task_id):
    for task in data["tasks"]:
        if task["id"] == task_id:
            return task
    raise TaskError(f"There is no task {task_id}.")


def next_due(scheduled, repeat, today):
    """The due date of the next task in a repeat.

    It counts from the schedule, not from the day the task was finished. A missed repeat does not pile up:
    the next date is the first one on the schedule after the scheduled date that is not before today.
    """
    step = REPEAT_DAYS[repeat]
    following = scheduled + datetime.timedelta(days=step)
    if following < today:
        behind = (today - following).days
        following += datetime.timedelta(days=-(-behind // step) * step)
    return following


def finish_task(data, task_id, today):
    """Mark a task done. Returns the task and the next task of its repeat, or None if it does not repeat."""
    task = find_task(data, task_id)
    if task["done"]:
        raise TaskError(f"Task {task_id} is already done.")
    task["done"] = True
    if not task["repeat"]:
        return task, None
    scheduled = datetime.date.fromisoformat(task["scheduled"] or task["due"])
    series = task.get("series") or task
    following = add_task(data, series["title"], today=today, due=next_due(scheduled, task["repeat"], today),
                         tags=series["tags"], repeat=task["repeat"])
    return task, following


def edit_task(data, task_id, title=None, due=None, tags=None, all_repeats=False):
    """Change an open task. On a repeating task the change is for this task only, unless all_repeats is true."""
    task = find_task(data, task_id)
    if task["done"]:
        raise TaskError(f"Task {task_id} is done. Edit the open one.")
    if title is None and due is None and tags is None:
        raise TaskError("Nothing to change. Give --title, --due or --tag.")
    if title is not None:
        title = clean_title(title)
    if tags is not None:
        tags = clean_tags(tags)
    if task["repeat"] and not all_repeats and (title is not None or tags is not None):
        # The next task copies the series, which an edit of this task alone leaves as it was.
        task.setdefault("series", {"title": task["title"], "tags": list(task["tags"])})
    if task["repeat"] and all_repeats and "series" in task:
        if title is not None:
            task["series"]["title"] = title
        if tags is not None:
            task["series"]["tags"] = tags
    if title is not None:
        task["title"] = title
    if tags is not None:
        task["tags"] = tags
    if due is not None:
        task["due"] = due.isoformat()
        if task["repeat"] and all_repeats:
            task["scheduled"] = task["due"]
    return task


def visible_tasks(data, tag=None, include_done=False):
    """The tasks to show, soonest due date first; tasks with no due date come last."""
    shown = [t for t in data["tasks"] if include_done or not t["done"]]
    if tag is not None:
        wanted = clean_tags([tag])
        shown = [t for t in shown if wanted and wanted[0] in t["tags"]]
    return sorted(shown, key=lambda t: (t["due"] is None, t["due"] or "", t["id"]))


def format_task(task):
    parts = [f"{task['id']}. {task['title']}"]
    if task["due"]:
        parts.append(f"(due {task['due']})")
    if task["tags"]:
        parts.append(" ".join("#" + tag for tag in task["tags"]))
    if task["repeat"]:
        parts.append(f"[{task['repeat']}]")
    return " ".join(parts)


def summary_lines(data, today):
    """The summary shown when the app opens: late tasks first, then the tasks due today."""
    day = today.isoformat()  # dates written as YYYY-MM-DD sort in date order as text
    open_tasks = [t for t in data["tasks"] if not t["done"] and t["due"]]
    late = sorted((t for t in open_tasks if t["due"] < day), key=lambda t: (t["due"], t["id"]))
    due_today = sorted((t for t in open_tasks if t["due"] == day), key=lambda t: t["id"])
    if not late and not due_today:
        return ["Nothing is late or due today."]
    lines = []
    if late:
        lines.append("Late")
        lines.extend("  " + format_task(t) for t in late)
    if due_today:
        lines.append("Due today")
        lines.extend("  " + format_task(t) for t in due_today)
    return lines

