"""The page in the browser. It lists the open tasks, adds them and finishes them, and listens on 127.0.0.1 only."""
import html
import http.server
from urllib.parse import parse_qs

from jotdown import dates, tasks
from jotdown.store import StoreError

HOST = "127.0.0.1"
DEFAULT_PORT = 8765

PAGE = """<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Jotdown</title>
</head>
<body>
<h1>Jotdown</h1>
<pre>{summary}</pre>
<h2>Add a task</h2>
<form method="post" action="/add">
<label>Title <input name="title" required></label>
<label>Due date <input name="due" placeholder="2027-03-19"></label>
<label>Tags <input name="tags" placeholder="garden home"></label>
<label>Repeat <select name="repeat">
<option value="">does not repeat</option>
<option value="daily">daily</option>
<option value="weekly">weekly</option>
</select></label>
<button>Add</button>
</form>
<h2>Open tasks</h2>
<ul>
{rows}</ul>
</body>
</html>
"""

ROW = """<li>{text} <form method="post" action="/done" style="display:inline">\
<input type="hidden" name="id" value="{id}"><button>Finish</button></form></li>
"""


class Page:
    """Answers the page's requests. It holds no network code, so a test can call handle() directly."""

    def __init__(self, store, today=None):
        self.store = store
        self.today = today  # a fixed date for tests; None means the computer's date

    def handle(self, method, path, headers, body=b""):
        """Answer one request and return (status, headers, body). The file is read again for every request."""
        today = self.today or dates.current_date()
        try:
            if method == "GET" and path == "/":
                return self.show(today)
            if method == "POST" and path == "/add":
                return self.add(self.form(body), today)
            if method == "POST" and path == "/done":
                return self.finish(self.form(body), today)
        except StoreError as error:
            return self.text(500, f"Jotdown stopped: {error}")
        return self.text(404, "Not found.")

    @staticmethod
    def form(body):
        return {name: values[0] for name, values in parse_qs(body.decode("utf-8")).items()}

    @staticmethod
    def text(status, message):
        return status, {"Content-Type": "text/plain; charset=utf-8"}, message.encode("utf-8")

    def show(self, today):
        data = self.store.load()
        rows = "".join(ROW.format(text=html.escape(tasks.format_task(task)), id=task["id"])
                       for task in tasks.visible_tasks(data))
        summary = html.escape("\n".join(tasks.summary_lines(data, today)))
        page = PAGE.format(summary=summary, rows=rows)
        return 200, {"Content-Type": "text/html; charset=utf-8"}, page.encode("utf-8")

    def add(self, form, today):
        data = self.store.load()
        try:
            due_text = form.get("due", "").strip()
            due = dates.parse_due(due_text) if due_text else None
            tasks.add_task(data, form.get("title", ""), today=today, due=due, tags=form.get("tags", "").split(),
                           repeat=form.get("repeat") or None)
        except (tasks.TaskError, dates.DateError) as error:
            return self.text(400, str(error))
        self.store.save(data)
        return 303, {"Location": "/"}, b""

    def finish(self, form, today):
        data = self.store.load()
        try:
            task_id = int(form.get("id", ""))
        except ValueError:
            return self.text(400, "A task number is needed.")
        try:
            tasks.finish_task(data, task_id, today)
        except tasks.TaskError as error:
            return self.text(400, str(error))
        self.store.save(data)
        return 303, {"Location": "/"}, b""


class Handler(http.server.BaseHTTPRequestHandler):
    """Passes each request to the server's Page."""

    def do_GET(self):
        self.answer("GET")

    def do_POST(self):
        self.answer("POST")

    def answer(self, method):
        length = int(self.headers.get("Content-Length") or 0)
        body = self.rfile.read(length) if length else b""
        status, headers, content = self.server.page.handle(method, self.path, self.headers, body)
        self.send_response(status)
        for name, value in headers.items():
            self.send_header(name, value)
        self.send_header("Content-Length", str(len(content)))
        self.end_headers()
        self.wfile.write(content)


def serve(store, port, out):
    """Serve the page on 127.0.0.1 until Ctrl+C."""
    with http.server.HTTPServer((HOST, port), Handler) as server:
        server.page = Page(store)
        print(f"Jotdown is at http://{HOST}:{port}/ . Press Ctrl+C to stop.", file=out, flush=True)
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            pass

