    shown = [t for t in data["tasks"] if include_done or not t["done"]]
    if tag is not None:
        wanted = clean_tags([tag])
        shown = [t for t in shown if wanted and wanted[0] in t["tags"]]
    return sorted(shown, key=lambda t: (t["due"] is None, t["due"] or "", t["id"]))


