"""Reading the due dates a person types."""
import datetime
import re

ISO_DATE = re.compile(r"\d{4}-\d{2}-\d{2}")


class DateError(ValueError):
    """The text is not a date Jotdown can read."""


def current_date():
    return datetime.date.today()


def parse_due(text):
    """Return the date for text written as YYYY-MM-DD, such as 2027-03-19."""
    words = text.strip()
    if ISO_DATE.fullmatch(words):
        try:
            return datetime.date.fromisoformat(words)
        except ValueError:
            pass
    raise DateError(f"{text!r} is not a date Jotdown can read. Write it as YYYY-MM-DD, such as 2027-03-19.")

