"""Reading the due dates a person types, with the tinydate library vendored in vendor/tinydate."""
import datetime
import importlib.util
from pathlib import Path

# tinydate is used as it is, from the project's vendor/tinydate folder, found from this file's own place
# so that it loads whichever folder jd runs from.
_TINYDATE = Path(__file__).resolve().parent.parent / "vendor" / "tinydate" / "tinydate.py"
_spec = importlib.util.spec_from_file_location("tinydate", _TINYDATE)
tinydate = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(tinydate)


class DateError(ValueError):
    """The text is not a date Jotdown can read."""


def current_date():
    return datetime.date.today()


def parse_due(text, today):
    """Return the date that text means, counted from today.

    Read: today, tomorrow, a weekday such as friday or fri (the next such day, never today), in 3 days,
    and a date such as 2027-03-19.
    """
    try:
        return tinydate.parse(text, today)
    except ValueError:
        raise DateError(f"{text!r} is not a date Jotdown can read. Try friday, in 3 days or 2027-03-19.") from None

