import datetime
import unittest

from jotdown import dates

TODAY = datetime.date(2027, 3, 15)  # a Monday


class DueDateTests(unittest.TestCase):
    def test_a_weekday_name_is_the_next_such_day(self):
        self.assertEqual(dates.parse_due("friday", TODAY), datetime.date(2027, 3, 19))
        self.assertEqual(dates.parse_due("Fri", TODAY), datetime.date(2027, 3, 19))

    def test_a_weekday_name_never_means_today(self):
        self.assertEqual(dates.parse_due("monday", TODAY), datetime.date(2027, 3, 22))

    def test_in_some_days(self):
        self.assertEqual(dates.parse_due("in 3 days", TODAY), datetime.date(2027, 3, 18))
        self.assertEqual(dates.parse_due("in 1 day", TODAY), datetime.date(2027, 3, 16))

    def test_a_full_date(self):
        self.assertEqual(dates.parse_due("2027-03-19", TODAY), datetime.date(2027, 3, 19))

    def test_today_and_tomorrow(self):
        self.assertEqual(dates.parse_due("today", TODAY), TODAY)
        self.assertEqual(dates.parse_due("tomorrow", TODAY), datetime.date(2027, 3, 16))

    def test_words_it_cannot_read_and_dates_that_do_not_exist_are_errors(self):
        for text in ("next fortnight", "2027-02-30", ""):
            with self.assertRaises(dates.DateError):
                dates.parse_due(text, TODAY)

