"""Reading the due dates a person types: today, tomorrow, a weekday, in N days or YYYY-MM-DD."""
import datetime
import re

WEEKDAYS = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]
IN_DAYS = re.compile(r"in (\d+) days?")


class DateError(ValueError):
    """The text is not a date Jotdown can read."""


def current_date():
    return datetime.date.today()


def parse_due(text, today):
    words = " ".join(text.lower().split())
    if words == "today":
        return today
    if words == "tomorrow":
        return today + datetime.timedelta(days=1)
    for number, name in enumerate(WEEKDAYS):
        if words in (name, name[:3]):
            return today + datetime.timedelta(days=(number - today.weekday()) % 7 or 7)
    found = IN_DAYS.fullmatch(words)
    if found:
        return today + datetime.timedelta(days=int(found.group(1)))
    try:
        return datetime.date.fromisoformat(words)
    except ValueError:
        raise DateError(f"{text!r} is not a date Jotdown can read. Try friday, in 3 days or 2027-03-19.") from None

